"""Independent mock-only completion checks on the fixed public101 producer.

The actual source/runtime binding verifier is active. Only the execution
boundary is injected; no original program, VM, container or store is called.
"""
from pathlib import Path
import hashlib,importlib.util,json,datetime
P=Path(__file__).resolve().parent
path=P/'repository/experiments/EXP-NISTSEED-6886da/aa-admission/test_aa_fixture_producer.py'
spec=importlib.util.spec_from_file_location('aa_v3_controls',path)
m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)

def field(raw,which,key,value,kind='result'):
 p=raw/which/(kind+'.json');x=json.loads(p.read_text());x[key]=value;m.dump(p,x)

def serial_change(raw,which,old,new):
 p=raw/which/'serial.raw';x=p.read_bytes().replace(old,new);m.put(p,x)
 body=raw/which/'program.stdout';m.put(body,body.read_bytes().replace(old,new))
 field(raw,which,'serial_sha256',m.digest(x))

def mutate(mode,raw,out,cache):
 if mode=='incidental':
  if out.name=='right':
   field(raw,'prover','elapsed_host_seconds',2)
   field(raw,'checker','elapsed_host_seconds',3)
   field(raw,'prover','utc','2026-11-01T00:00:00+00:00','started')
 elif mode=='timeout':field(raw,'prover','reason','host_watchdog')
 elif mode=='crash':field(raw,'prover','child_exit',1)
 elif mode in ('empty_certificate','wrong_root','malformed_certificate'):
  old=(raw/'prover/certificate.cformat').read_bytes()
  new=b'' if mode=='empty_certificate' else old.replace(b'101',b'103',1) if mode=='wrong_root' else b'101 -1 1 5\n'
  m.put(raw/'prover/certificate.cformat',new)
  serial_change(raw,'prover',old,new)
 elif mode=='checker_step_count':serial_change(raw,'checker',b'1: -1 1\n',b'')
 elif mode=='checker_rejection':serial_change(raw,'checker',b'1: -1 1',b'1: -1 0')
 elif mode=='labels':serial_change(raw,'prover',b'This number is prime',b'This number is composite')
 elif mode=='trace':
  if out.name=='right':serial_change(raw,'prover',b'% N_0=101',b'% N_0=102')
 elif mode=='configuration':
  for key,value in [('command',['/unexpected-program','-m','999']),('data_mode','empty'),('initramfs_sha256','0'*64),('stdin_sha256','0'*64)]:field(raw,'prover',key,value,'started')
 elif mode=='program':field(raw,'prover','program_sha256','0'*64,'started')
 elif mode=='duplicate_exit':serial_change(raw,'prover',b'__ECPP_CHILD_EXIT__ 0 timeout=0\n',b'__ECPP_CHILD_EXIT__ 0 timeout=0\n__ECPP_CHILD_EXIT__ 1 timeout=0\n')
 elif mode=='misordered_frame':
  p=raw/'prover/serial.raw';x=b'__ECPP_GUEST_COMPLETE__\n'+p.read_bytes().replace(b'__ECPP_GUEST_COMPLETE__\n',b'');m.put(p,x);field(raw,'prover','serial_sha256',m.digest(x))
 elif mode=='missing':(raw/'checker/qemu.stderr').unlink()
 elif mode=='extra':m.put(raw/'extra.raw',b'unexpected')
 elif mode=='empty_capture':
  for p in (raw/'prover').iterdir():p.unlink()
 elif mode=='image':
  p=next((cache/'images').iterdir());m.put(p,b'corrupt')
 elif mode=='nan_elapsed':field(raw,'prover','elapsed_host_seconds',float('nan'))
 elif mode=='input':m.put(raw/'input.txt',b'102\n')

cases=['baseline','incidental','timeout','crash','empty_certificate','wrong_root','malformed_certificate','checker_step_count','checker_rejection','labels','trace','configuration','program','duplicate_exit','misordered_frame','missing','extra','empty_capture','image','nan_elapsed','input']
rows=[]
for name in cases:
 t=m.Tests('runTest');t.setUp();b=m.Boundary(lambda raw,out,cache:mutate(name,raw,out,cache))
 try:
  result=m.aa.build_pair(t.root/'left',t.root/'right',t.manifest,b)
  rows.append({'case':name,'accepted':True,'equal':result['aa']['equal'],'boundary_calls':b.calls})
 except Exception as e:rows.append({'case':name,'accepted':False,'error_type':type(e).__name__,'error':str(e),'boundary_calls':b.calls})
 finally:t.tearDown()
for row in rows:
 row['expected_acceptance']=row['case'] in ('baseline','incidental')
 row['pass']=row['accepted']==row['expected_acceptance'] and row['boundary_calls']==2
receipt={'recorded_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'source_sha256':hashlib.sha256((path.parent/'aa_fixture_producer.py').read_bytes()).hexdigest(),'test_helper_sha256':hashlib.sha256(path.read_bytes()).hexdigest(),'verification_script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'cases':rows,'status':'PASS' if all(r['pass'] for r in rows) else 'FAIL','named_orders_executed':0,'legacy_program_executed':False,'vm_calls':0,'storage_attempts':0}
(P/'aa-final-independent-checks.json').write_text(json.dumps(receipt,indent=2)+'\n')
print(json.dumps(receipt,indent=2))
raise SystemExit(0 if receipt['status']=='PASS' else 1)
